mapper.select:
SELECT f.`id`, f.`name`, f.`path`, f.`file_type`, f.`file_size`, f.`content_hash`, f.`organism`, f.`genome_version`, f.`uploaded_by`, f.`created_at`, , u.`username` AS uploader_name FROM `data_files` f LEFT JOIN `users` u ON f.`uploaded_by` = u.`id`
AND f.`name` LIKE CONCAT('%', #{name}, '%')
AND f.`file_type` = #{fileType}
AND EXISTS (SELECT 1 FROM `data_file_projects` j WHERE j.`file_id` = f.`id` AND j.`project_id` = #{projectId})
AND f.`uploaded_by` = #{uploadedBy}
AND f.`organism` = #{organism}
ORDER BY f.`created_at` DESC

SELECT FROM `data_files` WHERE `file_type` = #{fileType}
AND EXISTS (SELECT 1 FROM `data_file_projects` j WHERE j.`file_id` = `data_files`.`id` AND j.`project_id` = #{projectId})
ORDER BY `created_at` DESC
